/* ---------- shaders ---------- */
const VS=`
attribute vec3 aPos;
attribute vec3 aNormal;
attribute vec2 aUV;
attribute float aFace;
attribute vec3 aTangent;
attribute vec3 aBinormal;
uniform mat4 uMVP, uModel;
uniform mat3 uNormalMat;
varying vec3 vN, vWP, vT, vB;
varying vec2 vUV;
varying float vFace;
void main(){
  vWP = (uModel * vec4(aPos,1.0)).xyz;
  vN  = normalize(uNormalMat * aNormal);
  vT  = normalize(uNormalMat * aTangent);
  vB  = normalize(uNormalMat * aBinormal);
  vUV = aUV;
  vFace = aFace;
  gl_Position = uMVP * vec4(aPos,1.0);
}`;

const FS=`
precision highp float;
varying vec3 vN, vWP, vT, vB;
varying vec2 vUV;
varying float vFace;
uniform sampler2D uFront, uBack;
uniform vec3 uCamPos, uL1, uL2, uBase, uRim, uAxisWorld;
uniform float uReeds, uDim, uSpecPower, uSpecBoost;

vec3 metalShade(vec3 base, vec3 N, vec3 V, float specMul){
  vec3 L1=normalize(uL1), L2=normalize(uL2);
  float d1=max(dot(N,L1),0.0);
  float d2=max(dot(N,L2),0.0);
  vec3 H1=normalize(L1+V); float s1=pow(max(dot(N,H1),0.0), uSpecPower);
  vec3 H2=normalize(L2+V); float s2=pow(max(dot(N,H2),0.0), 38.0);
  vec3 col = base*(0.16 + 0.55*d1 + 0.22*d2);
  col += vec3(1.0,0.97,0.86) * s1 * specMul * 1.05;
  col += vec3(0.82,0.86,1.0) * s2 * specMul * 0.45;
  float fres = pow(1.0 - max(dot(N,V),0.0), 4.0);
  col += uRim * fres * 0.55;
  return col;
}

vec3 emboss(sampler2D tex, vec3 N){
  float h  = texture2D(tex, vUV).a;
  float hx = texture2D(tex, vUV+vec2(1.0/512.0,0)).a;
  float hy = texture2D(tex, vUV+vec2(0,1.0/512.0)).a;
  float dU = hx - h;
  float dV = hy - h;
  vec3 Np = normalize(N - (dU*normalize(vT) + dV*normalize(vB))*0.07);
  vec3 col = mix(uBase*0.78, uBase*1.08, h);
  float spec = 0.7 + 0.7*h;
  vec3 V = normalize(uCamPos - vWP);
  return metalShade(col, Np, V, spec) * uDim;
}

void main(){
  vec3 N = normalize(vN);
  vec3 V = normalize(uCamPos - vWP);
  if(vFace < 0.5){
    gl_FragColor = vec4(emboss(uFront, N), 1.0);
  } else if(vFace < 1.5){
    gl_FragColor = vec4(emboss(uBack, N), 1.0);
  } else {
    float theta = vUV.x * 6.2831853;
    float ridge = sin(theta * uReeds);
    float ridge2= sin(theta * uReeds * 2.0 + 1.0);
    vec3 Np = normalize(N + uAxisWorld * (ridge*0.10));
    float groove = 0.5 + 0.5*ridge;
    vec3 col = mix(uBase*0.65, uBase*1.02, groove);
    float spec = 0.5 + 0.9*groove;
    gl_FragColor = vec4(metalShade(col, Np, V, spec) * uDim, 1.0);
  }
}`;

/* ---------- GL program / texture helpers ---------- */
function compile(gl,type,src){
  const s=gl.createShader(type); gl.shaderSource(s,src); gl.compileShader(s);
  if(!gl.getShaderParameter(s,gl.COMPILE_STATUS)){ console.error(gl.getShaderInfoLog(s)); }
  return s;
}
function makeProgram(gl){
  const p=gl.createProgram();
  gl.attachShader(p, compile(gl,gl.VERTEX_SHADER,VS));
  gl.attachShader(p, compile(gl,gl.FRAGMENT_SHADER,FS));
  gl.linkProgram(p);
  if(!gl.getProgramParameter(p,gl.LINK_STATUS)){ console.error(gl.getProgramInfoLog(p)); }
  return p;
}
function makeTexture(gl, drawFn){
  const cv=document.createElement('canvas'); cv.width=cv.height=512;
  const ctx=cv.getContext('2d'); drawFn(ctx);
  const tex=gl.createTexture();
  gl.bindTexture(gl.TEXTURE_2D, tex);
  gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL, false);
  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false);
  gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,cv);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR_MIPMAP_LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);
  gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
